SELECT s.name,count(*) AS n,avg(s.dur)/1e6 AS avg_ms,PERCENTILE(s.dur/1e6,50) AS p50_ms,PERCENTILE(s.dur/1e6,95) AS p95_ms,max(s.dur)/1e6 AS max_ms FROM slice s JOIN thread_track tt ON s.track_id=tt.id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid=22610 AND s.dur>0 AND s.name IN ('MediaCodec::dequeueOutputBuffer#native','MediaCodec::queueInputBuffer#native','MediaCodec::dequeueInputBuffer#native') GROUP BY s.name;
